import assert from 'node:assert/strict';
import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const root='F:/VisibleMedicine/staging/20261023-review-inbox-failure-focus',site=root+'/website';
const phase=process.argv[2];assert(['before-main','focused-main','originals-configured'].includes(phase));
const tests=phase==='originals-configured'?['tests/clinical-review-inbox-auto-return.test.mjs','tests/clinical-review-inbox-filter-recovery.test.mjs','tests/clinical-review-inbox-pagination-focus.test.mjs']:['tests/clinical-review-inbox-failure-focus.test.mjs'];
const log=root+'/logs/'+phase;assert(!fs.existsSync(log+'.json'));
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const component=phase==='before-main'?root+'/ClinicalReviewInbox.before.raw':site+'/components/ClinicalReviewInbox.tsx';
const args=['--max-old-space-size=128','--test','--test-concurrency=1','--test-reporter=tap',...tests];
const started={at:new Date().toISOString(),phase,cwd:site,args,component,componentSha256:sha(fs.readFileSync(component)),tests:tests.map(path=>({path,sha256:sha(fs.readFileSync(site+'/'+path))})),nodeHeapCapMiB:128};
fs.writeFileSync(log+'.started.json',JSON.stringify(started,null,2)+'\n',{flag:'wx'});
const result=spawnSync(process.execPath,args,{cwd:site,encoding:'utf8',windowsHide:true,maxBuffer:10*1024*1024,env:{...process.env,NODE_OPTIONS:'--max-old-space-size=128',RAYON_NUM_THREADS:'1',GOMAXPROCS:'2',VM_REVIEW_COMPONENT_PATH:component}});
fs.writeFileSync(log+'.stdout.txt',result.stdout??'',{flag:'wx'});fs.writeFileSync(log+'.stderr.txt',result.stderr??'',{flag:'wx'});
const counts=Object.fromEntries([...((result.stdout??'').matchAll(/^# (tests|pass|fail|cancelled|skipped|todo) (\d+)\s*$/gm))].map(m=>[m[1],Number(m[2])]));
const terminal={...started,finishedAt:new Date().toISOString(),exitCode:result.status,signal:result.signal,error:result.error?.message??null,counts,stdoutSha256:sha(result.stdout??''),stderrSha256:sha(result.stderr??'')};
fs.writeFileSync(log+'.json',JSON.stringify(terminal,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({phase,exitCode:result.status,counts}));
assert.equal(result.status,phase==='before-main'?1:0);assert.equal(counts.skipped,0);assert.equal(counts.cancelled,0);
if(phase==='before-main'){assert.equal(counts.tests,10);assert.equal(counts.fail,10);}else assert.equal(counts.fail,0);
